(()=>{'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'₹'+(n/100).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2});
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}},store=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let bag=load('forme_bag',[]),wish=load('forme_wishlist',[]),config={},products=[];
if(!Array.isArray(bag))bag=[];bag=bag.filter(x=>x&&typeof x.id==='string'&&typeof x.size==='string'&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=10).slice(0,30);if(!Array.isArray(wish))wish=[];
async function api(route,data,headers={}){const r=await fetch('/api/store/'+route,{method:data===undefined?'GET':'POST',headers:{...(data===undefined?{}:{'Content-Type':'application/json'}),...headers},body:data===undefined?undefined:JSON.stringify(data)});const b=await r.json();if(!r.ok)throw Object.assign(Error(b.error||'Please try again.'),{details:b});return b}
const count=()=>document.querySelectorAll('[data-bag-count]').forEach(el=>el.textContent=bag.reduce((n,x)=>n+x.quantity,0));
function save(){store('forme_bag',bag);try{sessionStorage.removeItem('forme_checkout_key')}catch{}count()}
const heading=(k,t,d='')=>'<p class="store-kicker">'+k+'</p><h1>'+t+'</h1>'+(d?'<p class="store-lead">'+d+'</p>':'');
const label=s=>({awaiting_payment:'Pending payment',creating_payment:'Preparing payment',paid:'Payment confirmed',order_confirmed:'Order confirmed',demo_confirmed:'Demo order confirmed',paid_review:'Payment received · support review',out_for_delivery:'Out for delivery',refund_pending:'Refund in progress',expired:'Payment window expired'}[s]||s.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase()));
function wishToggle(id){wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];store('forme_wishlist',wish)}
function track(event,productId){if(load('forme_consent',null)!=='all')return;const source=new URLSearchParams(location.search).get('utm_source')||sessionStorage.getItem('forme_source')||'direct';try{sessionStorage.setItem('forme_source',source)}catch{}api('analytics',{event,productId,source,consent:true}).catch(()=>{});if(window.gtag)window.gtag('event',event,{item_id:productId});if(window.fbq)window.fbq('trackCustom',event,{product_id:productId})}
function consent(){const choice=load('forme_consent',null);if(choice==='all'){if(config.ga4Id){const s=document.createElement('script');s.src='https://www.googletagmanager.com/gtag/js?id='+config.ga4Id;s.async=true;document.head.append(s);window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments)};gtag('js',new Date());gtag('config',config.ga4Id,{send_page_view:false})}if(config.metaPixelId){window.fbq=function(){window.fbq.callMethod?window.fbq.callMethod.apply(window.fbq,arguments):window.fbq.queue.push(arguments)};window.fbq.queue=[];window.fbq.loaded=true;window.fbq.version='2.0';const s=document.createElement('script');s.src='https://connect.facebook.net/en_US/fbevents.js';s.async=true;document.head.append(s);fbq('init',config.metaPixelId)}track('page_view');return}if(choice)return;if(!config.ga4Id&&!config.metaPixelId)return;document.body.insertAdjacentHTML('beforeend','<section class="consent-bar" aria-label="Privacy choices"><p>We use essential storage for your bag and sign-in. May we also use analytics and advertising cookies to understand visits and improve campaigns? <a href="/privacy">Privacy policy</a></p><div class="consent-actions"><button class="store-button outline" id="essentialCookies">Essential only</button><button class="store-button" id="allCookies">Allow analytics & ads</button></div></section>');$('#essentialCookies').onclick=()=>{store('forme_consent','essential');$('.consent-bar').remove()};$('#allCookies').onclick=()=>{store('forme_consent','all');$('.consent-bar').remove();consent()}}
function footer(){const contact=config.supportEmail?'<a href="mailto:'+esc(config.supportEmail)+'">'+esc(config.supportEmail)+'</a>':'<p>Business email pending confirmation</p>';document.body.insertAdjacentHTML('beforeend','<footer class="shop-footer"><div class="shop-footer-grid"><div><strong>FORME.</strong><p>Everyday Essentials. Elevated.<br>Premium Minimal Streetwear.</p>'+contact+(config.whatsapp?'<a href="https://wa.me/'+esc(config.whatsapp)+'" rel="noopener">WhatsApp support</a>':'')+'<p>Mon–Sat · 10 AM–7 PM IST<br>Target response: one business day</p></div><div><a href="/shop">Shop all</a><a href="/essentials">Plain essentials</a><a href="/graphics">Graphic collection</a><a href="/about">About Forme</a><a href="/contact">Contact</a><a href="/size-guide">Size guide</a><a href="/faq">FAQs</a></div><div><a href="/account">Your account</a><a href="/orders">Order history</a><a href="/track-order">Track order</a><a href="/shipping">Shipping</a><a href="/returns">Returns & exchanges</a><a href="/refunds">Cancellation & refunds</a><a href="/payment-policy">Payments</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></div></div><div class="footer-fine">© '+new Date().getFullYear()+' Forme. <button class="text-button" id="privacyChoices" style="color:inherit">Privacy choices</button></div></footer>');$('#privacyChoices').onclick=()=>{store('forme_consent',null);location.reload()}}
function image(p){return '<img src="'+esc(p.image||'')+'" '+(p.responsiveImages?.length?'srcset="'+p.responsiveImages.map(x=>esc(x.url)+' '+x.width+'w').join(', ')+'" sizes="(max-width:760px) 50vw, 400px" ':'')+'alt="'+esc(p.name)+'" loading="lazy" decoding="async">'}
function productCard(p){const stocked=Object.values(p.sizes||{}).some(x=>x>0),mrp=p.mrp>p.price?'<s class="store-muted">'+money(p.mrp*100)+'</s> ':'';return '<article class="shop-card"><a href="/products/'+encodeURIComponent(p.id)+'"><div class="shop-card-photo">'+image(p)+'</div><h2>'+esc(p.name)+'</h2><div class="store-row"><span>'+mrp+money(p.price*100)+'</span><span class="store-muted">'+esc(p.color)+'</span></div><p class="store-muted">'+(stocked?Object.keys(p.sizes).filter(s=>p.sizes[s]>0).join(' · '):p.pod?'Print on demand':'Currently unavailable')+'</p></a><button class="wishlist-button" data-wish="'+esc(p.id)+'" aria-label="'+(wish.includes(p.id)?'Remove from':'Add to')+' wishlist" aria-pressed="'+wish.includes(p.id)+'">'+(wish.includes(p.id)?'♥':'♡')+'</button></article>'}
function bindWishes(){document.querySelectorAll('[data-wish]').forEach(b=>b.onclick=()=>{wishToggle(b.dataset.wish);b.textContent=wish.includes(b.dataset.wish)?'♥':'♡';b.setAttribute('aria-pressed',String(wish.includes(b.dataset.wish)));if(location.pathname==='/wishlist')shop('wishlist')})}
function cartDrawer(p,size){let d=$('#cartDrawer');if(!d){document.body.insertAdjacentHTML('beforeend','<dialog class="cart-drawer" id="cartDrawer" aria-labelledby="drawerTitle"><button class="drawer-close" aria-label="Close bag">×</button><h2 id="drawerTitle">A good addition.</h2><div id="drawerContent"></div><p><a class="store-button" href="/cart">View your bag</a></p><p><a href="/shop">Keep exploring</a></p></dialog>');d=$('#cartDrawer');d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>document.body.classList.remove('cart-open'));d.onclick=e=>{if(e.target===d&&e.clientX<d.getBoundingClientRect().left)d.close()}}$('#drawerContent').innerHTML='<p>'+esc(p.name)+'</p><p class="store-muted">Size '+esc(size)+' · '+money(p.price*100)+'</p><p>'+bag.reduce((n,x)=>n+x.quantity,0)+' piece(s) in your bag.</p>';document.body.classList.add('cart-open');d.showModal()}
async function productBuy(){const id=decodeURIComponent(location.pathname.split('/')[2]),p=products.find(p=>p.id===id);if(!p)return;document.title=p.name+' | Forme';const canonical=document.createElement('link');canonical.rel='canonical';canonical.href=location.origin+location.pathname;document.head.append(canonical);const target=$('.product-actions');if(!target)return;const sizes=Object.entries(p.sizes).filter(([,q])=>q>0);target.insertAdjacentHTML('beforebegin','<section class="shop-buy"><fieldset class="size-picker" id="sizePicker"><legend>SELECT SIZE <span id="selectedSize"></span></legend><div class="size-options">'+[...new Set(['S','M','L','XL','XXL',...Object.keys(p.sizes)])].map(size=>'<label class="size-option '+(p.sizes[size]>0?'':'is-unavailable')+'"><input type="radio" name="productSize" value="'+esc(size)+'" '+(p.sizes[size]>0?'':'disabled')+' aria-label="'+esc(size)+(p.sizes[size]>0?'':' — unavailable')+'"><span>'+esc(size)+'</span></label>').join('')+'</div><p class="size-selection-note" id="sizeSelectionNote" aria-live="polite">'+(sizes.length?'Choose your usual size. Check the size guide for measurements.':'All sizes are currently unavailable.')+'</p></fieldset><input type="hidden" id="buySize" value=""><div class="buy-buttons"><button class="store-button red" id="addBag" '+(sizes.length?'':'disabled')+'>Add to bag · '+money(p.price*100)+'</button><button class="store-button outline wish" id="productWish" aria-label="Toggle wishlist">'+(wish.includes(p.id)?'♥':'♡')+'</button></div><p class="store-status" id="buyStatus" role="status"></p><p class="store-muted"><a href="/size-guide?product='+encodeURIComponent(p.id)+'">Size guide</a> · ₹'+config.shippingFee+' standard shipping · Free above ₹'+config.freeShippingAbove+'</p><p class="store-muted">'+esc(config.dispatchDays)+' processing. '+esc(config.deliveryDays)+'.'+(p.pod?' Personalised production: '+esc(p.podDays||'Timing to be confirmed before purchase'):'')+'</p><label class="store-muted" for="productPin">Check delivery PIN code</label><div class="field-grid"><input id="productPin" inputmode="numeric" maxlength="6" placeholder="6-digit PIN" style="padding:12px;font-size:16px"><button class="store-button outline" id="checkProductPin">Check delivery</button></div><p id="pinStatus" class="store-status" role="status"></p></section>');
document.querySelector('#sizes')?.closest('.spec')?.setAttribute('hidden','');
 document.body.insertAdjacentHTML('beforeend','<aside class="mobile-purchase-bar" aria-label="Buy this piece"><p>'+money(p.price*100)+'<small>'+esc(p.color)+'</small></p><button id="mobileAddBag" class="store-button red" '+(sizes.length?'':'disabled')+'>'+(sizes.length?'Choose size':'Unavailable')+'</button></aside>');
 document.querySelectorAll('[name="productSize"]').forEach(input=>input.addEventListener('change',()=>{$('#buySize').value=input.value;$('#selectedSize').textContent=' / '+input.value;$('#sizeSelectionNote').textContent='Size '+input.value+' selected';$('#buyStatus').textContent='';$('#buySize').dispatchEvent(new Event('change'))}));
 const focusSize=()=>{const picker=$('#sizePicker');picker.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});picker.querySelector('input:not(:disabled)')?.focus({preventScroll:true})};
 const syncMobileBuy=()=>{$('#mobileAddBag').textContent=$('#buySize').value?'Add to bag':'Choose size'};$('#buySize').addEventListener('change',syncMobileBuy);$('#mobileAddBag').onclick=()=>{if(!$('#buySize').value){focusSize()}else $('#addBag').click()};
 $('#productWish').onclick=()=>{wishToggle(p.id);$('#productWish').textContent=wish.includes(p.id)?'♥':'♡'};
$('#addBag').onclick=()=>{const size=$('#buySize').value;if(!size){$('#buyStatus').textContent='Choose your size first.';focusSize();return}const item=bag.find(x=>x.id===p.id&&x.size===size);if((item?.quantity||0)>=Math.min(10,p.sizes[size])){$('#buyStatus').textContent='Available quantity reached for this size.';return}if(item)item.quantity++;else bag.push({id:p.id,size,quantity:1});save();track('add_to_cart',p.id);cartDrawer(p,size)};
$('#checkProductPin').onclick=async()=>{try{const d=await api('serviceability',{pincode:$('#productPin').value});$('#pinStatus').textContent=d.available?'Delivery available'+(d.estimate?' · Courier estimate: '+d.estimate:''):'This PIN is not currently serviceable.'}catch(e){$('#pinStatus').textContent=e.message}};
if(p.mrp>p.price&&$('#price'))$('#price').insertAdjacentHTML('afterend','<span class="store-muted"><s>'+money(p.mrp*100)+'</s> · '+Math.round((1-p.price/p.mrp)*100)+'% off</span>');if(p.sku)target.insertAdjacentHTML('afterend','<p class="store-muted">SKU '+esc(p.sku)+'</p>');if(p.sizeChart?.length)target.insertAdjacentHTML('afterend','<details><summary>Garment measurements (cm)</summary>'+sizeTable(p)+'</details>');
track('product_view',p.id);
}
function sizeTable(p){return '<div class="table-scroll"><table><thead><tr><th>Size</th><th>Chest width</th><th>Length</th><th>Shoulder</th><th>Sleeve</th></tr></thead><tbody>'+p.sizeChart.map(r=>'<tr>'+['size','chest','length','shoulder','sleeve'].map(k=>'<td>'+esc(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
const main=$('#storeMain'),page=location.pathname.slice(1);let resetToken='';if(page==='reset-password'){resetToken=location.hash.slice(1);history.replaceState(null,'',location.pathname)}if(page==='order-confirmation'&&location.hash){const token=new URLSearchParams(location.hash.slice(1)).get('token'),id=new URLSearchParams(location.search).get('id');if(token&&id){const tokens=load('forme_order_tokens',{});tokens[id]=token;store('forme_order_tokens',tokens)}history.replaceState(null,'',location.pathname+location.search)}
function shop(kind){const title={shop:'Find your form.','new-arrivals':'The latest edit.',essentials:'Everyday essentials.',graphics:'Make a statement.',wishlist:'Your saved pieces.'}[kind];main.innerHTML=heading('THE FORME EDIT',title,'Considered silhouettes. Your own expression.')+'<div class="store-toolbar"><input id="searchShop" type="search" placeholder="Search the collection" aria-label="Search products"><select id="shopColour" aria-label="Colour"><option value="">All colours</option>'+[...new Set(products.map(p=>p.color))].map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><select id="shopSort" aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="new">Newest</option></select></div><p id="shopCount" class="store-muted" aria-live="polite"></p><section id="shopGrid" class="shop-grid"></section>';
function render(){let list=products.filter(p=>(kind!=='essentials'||p.category==='plain')&&(kind!=='graphics'||p.category!=='plain')&&(kind!=='wishlist'||wish.includes(p.id))&&p.name.toLowerCase().includes($('#searchShop').value.toLowerCase())&&(!$('#shopColour').value||p.color===$('#shopColour').value));const sort=$('#shopSort').value;if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='featured')list.sort((a,b)=>Number(b.featured)-Number(a.featured));if(sort==='new'||kind==='new-arrivals')list.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));if(kind==='new-arrivals')list=list.slice(0,12);$('#shopCount').textContent=list.length+' '+(list.length===1?'piece':'pieces');$('#shopGrid').innerHTML=list.map(productCard).join('')||'<p>No pieces here yet. <a href="/shop">Explore the full collection</a>.</p>';bindWishes();document.querySelectorAll('.shop-card-photo img').forEach(img=>img.onerror=()=>{img.replaceWith(Object.assign(document.createElement('p'),{className:'media-fallback',textContent:'Product photo coming soon'}))})}$('#searchShop').oninput=render;$('#shopColour').onchange=render;$('#shopSort').onchange=render;render()}

function policy(){
 const pending=!config.legalName||!config.businessAddress||!config.supportEmail;
 const support=config.supportEmail?'<a href="mailto:'+esc(config.supportEmail)+'">'+esc(config.supportEmail)+'</a>':'our website contact form (official business email pending)';
 const shipping='<h2>Where we deliver</h2><p>Across serviceable PIN codes in India. Your PIN code is checked before accepting a live order.</p><h2>Charges</h2><p>Standard shipping is ₹'+config.shippingFee+'. Free standard shipping applies on orders above ₹'+config.freeShippingAbove+'. The final delivery charge appears before payment.</p><h2>Processing and delivery</h2><p>In-stock orders are processed within '+esc(config.dispatchDays)+'. Estimated delivery is '+esc(config.deliveryDays)+'. Courier estimates are not guaranteed delivery dates. Personalised print-on-demand items may need additional production time, disclosed before payment.</p><h2>Tracking</h2><p>Tracking details are provided after dispatch. Check your order page for courier updates.</p>';
 const returns='<h2>Eligibility</h2><p>Request eligible returns or exchanges within '+config.returnDays+' days of delivery. Items must be unused, unwashed and retain their original tags. Size exchanges depend on stock availability.</p><h2>Return delivery charges</h2><p>The proposed reverse shipping charge for customer-requested size exchanges or change-of-mind returns is ₹'+config.reverseShipping+'. This charge will be disclosed before purchase. Incorrect, damaged or defective items are resolved without additional shipping charges to you.</p><h2>Personalised products</h2><p>Personalised print-on-demand items are not eligible for change-of-mind returns. Defective, damaged or incorrect items remain eligible for resolution. Applicable consumer rights are preserved.</p><h2>How to request</h2><p>Open your order from your account or the private order link saved after checkout, then submit a return or exchange request with the reason. You can also contact '+support+'.</p>';
 const policies={
 shipping:['DELIVERY, CONSIDERED','Shipping policy',shipping],
 returns:['FIND THE RIGHT FIT','Returns & exchanges',returns],
 refunds:['CLEAR FROM THE START','Cancellation & refunds','<h2>Before dispatch</h2><p>You may request cancellation before dispatch. Personalised orders may have production conditions disclosed before payment; contact us promptly if production has started.</p><h2>Refund timing</h2><p>Approved refunds are initiated within 5–7 business days after inspection. Refunds use the original payment method where possible. Payment provider and bank processing may add time.</p><h2>Request a cancellation</h2><p>Use the request form on your order page. Unpaid orders can be cancelled directly before the payment window ends. Paid orders need a review and refund confirmation.</p>'+returns],
 'payment-policy':['SECURE CHECKOUT','Payment policy','<h2>Payment methods</h2><p>Razorpay checkout is prepared for UPI, credit and debit cards, net banking and supported wallets. Availability depends on your bank and the activated merchant account. No raw card details are stored on this website.</p><h2>Payment confirmation</h2><p>Orders are confirmed only after server verification of the captured payment. A browser success message alone is not proof of payment.</p><h2>Cash on delivery</h2><p>COD is currently '+(config.codEnabled?'being prepared; it is not available at checkout yet':'disabled')+'.</p><h2>Store status</h2><p>'+(!config.checkoutEnabled?'Live checkout is closed until business verification, gateway credentials and launch requirements are complete.':'Checkout mode: '+esc(config.mode)+'.')+'</p>'],
 privacy:['YOUR INFORMATION','Privacy policy','<h2>Who operates the store</h2><p>'+esc(config.legalName||'Legal business name pending')+' · '+esc(config.businessAddress||'Registered address pending')+'. Contact: '+support+'. Grievance contact: '+esc(config.grievanceContact||'Pending confirmation')+'.</p><h2>Information we use</h2><p>Account name, email and a salted password hash; shipping and billing details; order and payment references; support and return requests. These support account access, fulfilment, customer service and transaction records. We do not store raw card details.</p><h2>Service providers</h2><p>When configured, Razorpay processes payments, Shiprocket and courier partners receive fulfilment details, and the email provider delivers transactional updates. We share the details needed for those services.</p><h2>Browser storage and analytics</h2><p>Essential cookies keep you signed in. Your bag, wishlist, privacy choices and guest order access tokens are stored in your browser. Optional GA4 and Meta tracking load only after permission. You can change your choice from the footer. Changing to essential-only stops future tracking after reload; clearing existing provider cookies may require your browser settings.</p><h2>Retention and requests</h2><p>Session records expire after seven days and password recovery links after 30 minutes. Order and account retention periods must be finalised for applicable business and legal requirements before launch. Contact support for access, correction, deletion and privacy complaints, subject to lawful record retention.</p><h2>Marketing</h2><p>No automated marketing or abandoned-checkout communications are sent without appropriate consent.</p>'],
 terms:['THE EVERYDAY DETAILS','Terms & conditions','<h2>Seller</h2><p>'+esc(config.legalName||'Legal business name pending')+' · '+esc(config.businessAddress||'Registered address pending')+'. Support: '+support+'.</p><h2>Orders and availability</h2><p>Products are subject to availability. Prices, discounts, shipping and applicable taxes appear in the order summary before payment. A short stock reservation supports payment; an expired reservation may need support review if a late payment arrives.</p><h2>Product information</h2><p>Review size measurements, fit, care and personalised-production details before purchase. Screen colours can differ from garments. We do not make unverified sustainability or fabric claims.</p><h2>Customer policies</h2><p>Our <a href="/shipping">shipping</a>, <a href="/returns">return and exchange</a>, <a href="/refunds">cancellation/refund</a> and <a href="/payment-policy">payment</a> policies form part of the purchase terms. Applicable consumer rights are preserved.</p><h2>Account access</h2><p>Keep your password and private guest order links secure. Contact support if you believe someone has accessed your account.</p>'],
 about:['PREMIUM MINIMAL STREETWEAR','Everyday Essentials. Elevated.','<h2>Less noise. More you.</h2><p>Forme brings a considered approach to your daily rotation: relaxed proportions, minimal essentials and graphic pieces with room for individual expression.</p><p>We focus on oversized and drop-shoulder T-shirts. Explore each piece through its photographs, fit notes and verified specifications, then choose the colour and size that feels like you.</p><p><a class="store-button" href="/shop">Explore Forme</a></p>'],
 faq:['A FEW THINGS YOU MIGHT ASK','The details, answered.','<details open><summary>How do I choose a size?</summary><p>Measure a tee you already own and compare flat garment measurements on the product size chart. Do not assume all fits use the same measurements.</p></details><details><summary>When will my order arrive?</summary><p>'+esc(config.dispatchDays)+' processing plus an estimated '+esc(config.deliveryDays)+'. Live delivery is subject to your PIN code and courier availability.</p></details><details><summary>Can I exchange a size?</summary><p>Eligible items can be requested within '+config.returnDays+' days of delivery, subject to condition and stock. See the <a href="/returns">full policy</a>.</p></details><details><summary>Can I order without an account?</summary><p>Yes. Guest checkout is supported. Save the private order link provided after checkout to view and manage your order.</p></details><details><summary>Do you offer cash on delivery?</summary><p>COD is disabled initially. Checkout displays the currently available payment methods.</p></details><details><summary>How do I contact you?</summary><p>Use our <a href="/contact">contact form</a>. Support hours are Monday–Saturday, 10 AM–7 PM IST. We target an initial response within one business day.</p></details>']
 };
 if(policies[page]){const [k,t,s]=policies[page];main.classList.add('store-policy');main.innerHTML=heading(k,t)+(page==='about'?'':!config.policiesApproved||pending?'<div class="store-notice">Pre-launch policy draft. Business identity, contacts and final policy approval remain pending. Live orders stay disabled.</div>':'')+s;return true}
 if(page==='size-guide'){main.innerHTML=heading('YOUR FIT, YOUR FORM','Find your everyday fit.','Lay your favourite tee flat. Measure chest width, length, shoulder and sleeve in centimetres, then compare with the verified garment chart.')+'<label for="chartProduct">Choose a piece</label><select id="chartProduct" style="padding:14px;width:100%;font-size:16px;margin:15px 0"><option value="">Select product</option>'+products.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+'</option>').join('')+'</select><div id="chart"></div>';const render=()=>{const p=products.find(x=>x.id===$('#chartProduct').value);$('#chart').innerHTML=p?.sizeChart?.length?sizeTable(p):'<div class="store-notice">Verified measurements have not been entered for this piece. We have not invented a chart. Please contact the studio before choosing a size.</div>'};$('#chartProduct').value=new URLSearchParams(location.search).get('product')||'';$('#chartProduct').onchange=render;render();return true}return false;
}
function totals(q){return '<div class="store-row"><span>Products</span><span>'+money(q.subtotal)+'</span></div>'+(q.discount?'<div class="store-row"><span>Discount</span><span>−'+money(q.discount)+'</span></div>':'')+'<div class="store-row"><span>Standard shipping</span><span>'+(q.shipping?money(q.shipping):'Free')+'</span></div><div class="store-row"><span>Tax'+(q.taxInclusive?' included':'')+'</span><span>'+(q.taxConfirmed?money(q.tax):'Pending confirmation')+'</span></div><div class="store-row total"><span>Total</span><span>'+money(q.total)+'</span></div>'}
let activeCoupon=load('forme_coupon','');
async function bagPage(checkout=false){main.innerHTML=heading('YOUR EVERYDAY ROTATION',checkout?'One step closer.':'Your bag.','Thoughtful pieces. Picked by you.');if(!bag.length){main.insertAdjacentHTML('beforeend','<div class="store-empty"><h2>Your next favourite is waiting.</h2><a href="/shop" class="store-button">Explore the collection</a></div>');return}
try{const q=await api('quote',{items:bag,coupon:activeCoupon});main.insertAdjacentHTML('beforeend','<div class="store-grid"><section><div id="bagItems">'+q.items.map((x,i)=>'<article class="bag-line">'+image(x)+'<div><h2><a href="/products/'+encodeURIComponent(x.id)+'">'+esc(x.name)+'</a></h2><p class="store-muted">'+esc(x.color)+' · Size '+esc(x.size)+'</p><label>Qty <select data-qty="'+i+'" aria-label="Quantity for '+esc(x.name)+'">'+Array.from({length:10},(_,j)=>'<option '+(x.quantity===j+1?'selected':'')+'>'+(j+1)+'</option>').join('')+'</select></label> <button class="text-button" data-remove="'+i+'">Remove</button>'+(x.pod?'<p class="store-muted">Personalised production: '+esc(x.podDays||'Timing must be confirmed')+'</p>':'')+'</div><div>'+money(x.unitAmount*x.quantity)+'</div></article>').join('')+'</div><div id="checkoutForm"></div></section><aside class="store-panel"><h2>The details</h2>'+totals(q)+'<form id="couponForm" class="store-form" style="margin-top:25px"><label>Promo code<input id="couponCode" value="'+esc(activeCoupon)+'" maxlength="30"></label><button class="store-button outline">Apply code</button><button class="text-button" type="button" id="removeCoupon" '+(activeCoupon?'':'hidden')+'>Remove code</button><p id="couponStatus" class="store-status" role="status"></p></form>'+(!config.checkoutEnabled?'<div class="store-notice">Pre-launch preview. Payments open after business, tax, payment and shipping setup is confirmed.</div>':config.mode!=='live'?'<div class="store-notice">'+esc(config.mode.toUpperCase())+' MODE · No real fulfilment.</div>':'')+(!checkout?'<a href="/checkout" class="store-button">Continue to checkout</a>':'')+'<p class="store-muted">₹'+config.shippingFee+' standard delivery. Free above ₹'+config.freeShippingAbove+'. <a href="/returns">7-day eligible returns</a>.</p><a href="/shop">Keep exploring</a></aside></div>');
main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{bag.splice(Number(b.dataset.remove),1);save();bagPage(checkout)});main.querySelectorAll('[data-qty]').forEach(s=>s.onchange=()=>{bag[Number(s.dataset.qty)].quantity=Number(s.value);save();bagPage(checkout)});$('#couponForm').onsubmit=async e=>{e.preventDefault();try{const code=$('#couponCode').value.trim().toUpperCase();await api('quote',{items:bag,coupon:code});activeCoupon=code;store('forme_coupon',code);sessionStorage.removeItem('forme_checkout_key');bagPage(checkout)}catch(err){$('#couponStatus').textContent=err.message}};$('#removeCoupon').onclick=()=>{activeCoupon='';store('forme_coupon','');bagPage(checkout)};if(checkout){track('begin_checkout');checkoutForm(q)}
}catch(e){main.insertAdjacentHTML('beforeend','<div class="store-notice" role="alert">'+esc(e.message)+(load('forme_last_order','')?' <a href="/order-confirmation?id='+esc(load('forme_last_order',''))+'">Review your previous checkout</a>':'')+'</div><button id="clearCoupon" class="text-button">Remove coupon</button><section id="repairBag"></section>');$('#clearCoupon').onclick=()=>{activeCoupon='';store('forme_coupon','');bagPage(checkout)};bag.forEach((x,i)=>{const p=document.createElement('p');p.textContent=(products.find(p=>p.id===x.id)?.name||'Unavailable piece')+' · '+x.size+' ';const b=document.createElement('button');b.className='text-button';b.textContent='Remove';b.onclick=()=>{bag.splice(i,1);save();bagPage(checkout)};p.append(b);$('#repairBag').append(p)})}}
function addressFields(prefix=''){return '<div class="field-grid">'+[['name','Full name','name'],['phone','Mobile number','tel'],['email','Email address','email'],['house','House / flat number','address-line1'],['building','Building name (optional)','address-line2'],['street','Street and area','address-line2'],['landmark','Landmark (optional)','off'],['pincode','PIN code','postal-code'],['city','City','address-level2'],['state','State','address-level1']].map(([name,text,auto])=>'<label>'+text+'<input name="'+prefix+name+'" '+(['building','landmark'].includes(name)?'':'required')+' type="'+(name==='email'?'email':'text')+'" autocomplete="'+(prefix?'billing ':'shipping ')+auto+'" '+(name==='phone'?'inputmode="tel" maxlength="13"':name==='pincode'?'inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6"':'maxlength="180"')+'></label>').join('')+'</div>'}
function checkoutForm(q){$('#checkoutForm').innerHTML='<h2>Where should your Forme go?</h2><p class="store-muted">Guest checkout is welcome. <a href="/account">Sign in</a> to see this order in your account.</p><form class="store-form" id="placeOrder">'+addressFields()+'<p class="store-muted">Country: India</p><label class="check"><input type="checkbox" id="billingDifferent">Use a different billing address</label><fieldset id="billingFields" hidden disabled><legend>Billing address</legend>'+addressFields('billing_')+'</fieldset><label>Order notes (optional)<textarea name="notes" maxlength="500"></textarea></label><button class="store-button outline" id="checkDelivery" type="button">Check PIN code serviceability</button><p id="deliveryStatus" class="store-status" role="status"></p>'+(config.codEnabled&&config.mode==='live'?'<label>Payment method<select name="paymentMethod"><option value="prepaid">Pay online securely</option><option value="cod">Cash on delivery</option></select></label>':'')+'<label class="check"><input type="checkbox" name="whatsappUpdates">Send optional transactional order updates on WhatsApp. No marketing messages.</label><label class="check"><input type="checkbox" name="acceptTerms" required><span>I have read the <a href="/terms">terms</a>, <a href="/shipping">shipping</a>, <a href="/returns">return/exchange</a> and <a href="/refunds">refund policies</a>, including the proposed ₹'+config.reverseShipping+' reverse shipping charge for eligible change-of-mind requests.</span></label><button type="submit" class="store-button red" '+(config.checkoutEnabled?'':'disabled')+'>'+(config.mode==='demo'?'Place demo order':config.checkoutEnabled?'Continue to secure payment':'Live checkout awaiting setup')+'</button><p id="checkoutStatus" class="store-status" role="status"></p></form>';
$('#billingDifferent').onchange=e=>{$('#billingFields').hidden=!e.target.checked;$('#billingFields').disabled=!e.target.checked};
$('#checkDelivery').onclick=async()=>{try{const d=await api('serviceability',{pincode:$('#placeOrder [name=pincode]').value,quantity:bag.reduce((n,x)=>n+x.quantity,0)});$('#deliveryStatus').textContent=d.available?'Delivery is available. Estimated transit is not guaranteed.':'This PIN code is not currently serviceable.'}catch(e){$('#deliveryStatus').textContent=e.message}};
$('#placeOrder').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const fields=Object.fromEntries(new FormData(e.target)),address={...fields,billingDifferent:$('#billingDifferent').checked,billing:Object.fromEntries(Object.entries(fields).filter(([k])=>k.startsWith('billing_')).map(([k,v])=>[k.slice(8),v]))};const fingerprint=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({items:bag,coupon:activeCoupon,address}))))).map(n=>n.toString(16).padStart(2,'0')).join('');if(sessionStorage.getItem('forme_checkout_fingerprint')!==fingerprint){sessionStorage.removeItem('forme_checkout_key');sessionStorage.setItem('forme_checkout_fingerprint',fingerprint)}let key=sessionStorage.getItem('forme_checkout_key');if(!key){key=crypto.randomUUID();sessionStorage.setItem('forme_checkout_key',key)}const result=await api('orders',{items:bag,coupon:activeCoupon,address,acceptTerms:!!fields.acceptTerms,paymentMethod:fields.paymentMethod||'prepaid',analyticsConsent:load('forme_consent',null)==='all',whatsappUpdates:!!fields.whatsappUpdates,source:sessionStorage.getItem('forme_source')||'direct'},{'Idempotency-Key':key});store('forme_last_order',result.order.id);if(result.token){const tokens=load('forme_order_tokens',{});tokens[result.order.id]=result.token;store('forme_order_tokens',tokens)}if(['expired','cancelled','refunded'].includes(result.order.status)){sessionStorage.removeItem('forme_checkout_key');throw Error('Your previous checkout has closed. Submit again to start a fresh order.')}if(!['creating_payment','awaiting_payment'].includes(result.order.status)){bag=[];save();sessionStorage.removeItem('forme_checkout_key');location.href='/order-confirmation?id='+result.order.id;return}if(result.order.total!==q.total){location.href='/order-confirmation?id='+result.order.id;return}if(!result.gatewayOrder)throw Error('Payment setup is still pending. Review your order before retrying.');await razorpay(result,address);b.disabled=false}catch(err){if(err.details?.orderId){const tokens=load('forme_order_tokens',{});tokens[err.details.orderId]=err.details.token;store('forme_order_tokens',tokens);$('#checkoutStatus').innerHTML=esc(err.message)+' <a href="/order-confirmation?id='+esc(err.details.orderId)+'">View pending order</a>'}else $('#checkoutStatus').textContent=err.message;b.disabled=false}}}
async function razorpay(result,address){if(!window.Razorpay)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=resolve;s.onerror=()=>reject(Error('Payment checkout could not load'));document.head.append(s)});const o=result.order,token=load('forme_order_tokens',{})[o.id];const r=new window.Razorpay({key:result.paymentKey||config.paymentKey,order_id:result.gatewayOrder,amount:o.total,currency:'INR',name:'Forme',description:o.id,prefill:{name:address.name,email:address.email,contact:address.phone},theme:{color:'#df2528'},handler:async data=>{try{const verified=await api('orders/'+o.id+'/verify',data,{'X-Order-Token':token});if(['paid','paid_review'].includes(verified.status)){bag=[];save();sessionStorage.removeItem('forme_checkout_key');location.href='/order-confirmation?id='+o.id}}catch(e){($('#checkoutStatus')||$('#orderStatus')).textContent=e.message+' Your order reference is '+o.id+'. Do not pay again until its status is checked.'}},modal:{ondismiss:()=>{($('#checkoutStatus')||$('#orderStatus')).textContent='Payment was not completed. Your order is reserved briefly; use its private order page to review it.'}}});r.on('payment.failed',()=>{($('#checkoutStatus')||$('#orderStatus')).textContent='Payment failed. Your bank may take time to release any pending debit.'});r.open()}

async function account(register=false,session=null){const savedEmail=$('#authForm [name="email"]')?.value||'';const s=session||await api('session');if(s.customer){main.innerHTML=heading('YOUR FORM, YOUR SPACE','Hello, '+esc(s.customer.name)+'.')+'<div class="store-grid"><section class="store-panel"><h2>Your account</h2><p>'+esc(s.customer.email)+'</p><p><a href="/orders">View your order history</a></p><p><a href="/wishlist">Your wishlist</a></p><button id="logout" class="store-button outline">Sign out</button></section><aside><h2>Here when you need us.</h2><p>Monday–Saturday, 10 AM–7 PM IST.</p><a href="/contact">Contact support</a></aside></div>';$('#logout').onclick=async()=>{await api('logout',{});account()};return}
main.innerHTML=heading('YOUR FORM, YOUR SPACE',register?'Make yourself at home.':'Good to see you.')+'<div class="store-grid auth-layout"><section class="store-panel auth-panel"><div class="account-tabs" role="group" aria-label="Account access"><button id="signIn" class="'+(!register?'active':'')+'">Sign in</button><button id="signUp" class="'+(register?'active':'')+'">Create account</button></div><form id="authForm" class="store-form">'+(register?'<label>Your name<input name="name" autocomplete="name" minlength="2" maxlength="80" required></label>':'')+'<label>Email<input name="email" type="email" autocomplete="email" maxlength="254" inputmode="email" autocapitalize="none" spellcheck="false" required></label><label for="authPassword">Password</label><div class="password-field"><input id="authPassword" name="password" type="password" autocomplete="'+(register?'new-password':'current-password')+'" '+(register?'minlength="12" ':'')+'maxlength="128" aria-describedby="authStatus" required><button type="button" class="password-toggle" aria-controls="authPassword" aria-pressed="false">Show</button></div>'+(register?'<p class="store-muted">Use at least 12 characters. Choose a unique password.</p>':'')+'<button type="submit" class="store-button red">'+(register?'Create account':'Sign in')+'</button><p id="authStatus" class="store-status" role="status"></p></form><a href="/forgot-password">Forgot your password?</a><p class="store-muted">Read our <a href="/privacy">privacy policy</a> and <a href="/terms">terms</a>.</p></section><aside><h2>Your everyday, considered.</h2><p class="store-lead">Order history, saved pieces and a little more room for your own form.</p><p class="store-muted">Guest checkout is always available.</p><a href="/shop">Explore the collection</a></aside></div>';
$('#authForm [name="email"]').value=savedEmail;
$('#signIn').onclick=()=>account(false,s);$('#signUp').onclick=()=>account(true,s);
$('.password-toggle').onclick=e=>{const input=$('#authPassword'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-pressed',String(show))};
$('#authForm').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('[type="submit"]'),text=b.textContent; b.disabled=true;form.setAttribute('aria-busy','true');b.textContent=register?'Creating your account…':'Signing you in…';$('#authStatus').textContent='';try{const result=await api(register?'register':'login',Object.fromEntries(new FormData(form)));await account(false,result)}catch(err){$('#authStatus').textContent=err.message;$('#authStatus').setAttribute('tabindex','-1');$('#authStatus').focus();b.disabled=false;b.textContent=text;form.removeAttribute('aria-busy')}}}
function recovery(){const reset=page==='reset-password';main.innerHTML=heading('YOUR ACCOUNT',reset?'A fresh start.':'Let’s get you back in.')+'<form id="recovery" class="store-form store-panel" style="max-width:500px"><label>'+(reset?'New password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required>':'Account email<input name="email" type="email" autocomplete="email" required>')+'</label><button class="store-button">'+(reset?'Reset password':'Send recovery link')+'</button><p class="store-status" id="recoveryStatus" role="status"></p></form>';$('#recovery').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(reset)data.token=resetToken;const d=await api(reset?'reset-password':'forgot-password',data);$('#recoveryStatus').textContent=d.message||'Password updated. Sign in with your new password.'}catch(err){$('#recoveryStatus').textContent=err.message}finally{b.disabled=false}}}
async function orders(){main.innerHTML=heading('YOUR EVERYDAY JOURNEY','Your orders.');try{const list=await api('orders');main.insertAdjacentHTML('beforeend',list.map(o=>'<article class="order-card"><div class="store-row"><strong>'+esc(o.id)+'</strong><span>'+esc(label(o.status))+'</span></div><p>'+new Date(o.created).toLocaleDateString('en-IN')+' · '+money(o.total)+(o.mode!=='live'?' · '+esc(o.mode.toUpperCase()):'')+'</p><a href="/order-confirmation?id='+esc(o.id)+'">View order & tracking</a></article>').join('')||'<div class="store-empty">No orders yet. <a href="/shop">Find your form</a>.</div>')}catch(e){main.insertAdjacentHTML('beforeend','<p>'+esc(e.message)+'</p><a class="store-button" href="/account">Sign in</a><p class="store-muted">Guest orders can be opened using the private order link saved at checkout.</p>')}}
async function orderPage(id){const tokens=load('forme_order_tokens',{}),token=new URLSearchParams(location.hash.slice(1)).get('token')||tokens[id];if(token){tokens[id]=token;store('forme_order_tokens',tokens);if(location.hash)history.replaceState(null,'',location.pathname+location.search)}const headers=token?{'X-Order-Token':token}:{};
try{const o=await api('orders/'+id,undefined,headers);if(o.mode==='live'&&['paid','processing','packed','shipped','delivered'].includes(o.status)&&load('forme_consent',null)==='all'&&!sessionStorage.getItem('forme_purchase_'+o.id)){if(window.gtag)gtag('event','purchase',{transaction_id:o.id,currency:'INR',value:o.total/100,shipping:o.shipping/100,tax:o.tax/100,items:o.items.map(x=>({item_id:x.id,item_name:x.name,price:x.unitAmount/100,quantity:x.quantity}))});if(window.fbq)fbq('track','Purchase',{currency:'INR',value:o.total/100},{eventID:o.id});sessionStorage.setItem('forme_purchase_'+o.id,'1')}main.innerHTML=heading('YOUR FORME JOURNEY',esc(o.id),esc(label(o.status)))+(o.mode!=='live'?'<div class="store-notice">'+esc(o.mode.toUpperCase())+' ORDER · No live fulfilment. Demo orders do not represent a payment.</div>':'')+'<div class="store-grid"><section><div class="store-panel"><h2>Your pieces</h2>'+o.items.map(x=>'<div class="store-row"><span>'+esc(x.name)+'<br><small>Size '+esc(x.size)+' · Qty '+x.quantity+'</small></span><span>'+money(x.unitAmount*x.quantity)+'</span></div>').join('')+'</div><h2>Delivery address</h2><p>'+esc(o.address.name)+'<br>'+esc([o.address.house,o.address.building,o.address.street,o.address.city,o.address.state,o.address.pincode].filter(Boolean).join(', '))+'</p><p class="store-muted">'+esc(config.dispatchDays)+' processing · Estimated '+esc(config.deliveryDays)+'</p><div id="orderActions"></div><p id="orderStatus" class="store-status" role="status"></p></section><aside class="store-panel"><h2>Order summary</h2>'+totals({...o,taxInclusive:o.pricing?.taxInclusive??config.taxInclusive,taxConfirmed:o.pricing?.taxConfirmed??config.taxConfirmed})+(o.refundedAmount?'<div class="store-row"><span>Refunded</span><span>'+money(o.refundedAmount)+'</span></div>':'')+(token?'<p><button id="copyOrderLink" class="text-button">Copy private order link</button></p><p class="store-muted">Keep this link private. It grants access to this order.</p>':'')+'<p><a href="/contact">Contact support</a></p></aside></div>';
if(token)$('#copyOrderLink').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/order-confirmation?id='+o.id+'#token='+token);$('#copyOrderLink').textContent='Private link copied'}catch{$('#orderStatus').textContent='Clipboard unavailable. This browser has saved your guest access locally.'}};
if(o.status==='awaiting_payment'&&config.checkoutEnabled){$('#orderActions').insertAdjacentHTML('beforeend','<button class="store-button red" id="resumePayment">Continue secure payment</button>');$('#resumePayment').onclick=async()=>{try{const result=await api('orders/'+id+'/resume',{},headers);await razorpay(result,o.address)}catch(e){$('#orderStatus').textContent=e.message}}}if((['creating_payment','awaiting_payment','demo_confirmed'].includes(o.status)||['cod','free'].includes(o.paymentMethod)&&['order_confirmed','processing','packed'].includes(o.status)))$('#orderActions').insertAdjacentHTML('beforeend','<button class="store-button outline" id="cancelOrder">Cancel order</button>');
if($('#cancelOrder'))$('#cancelOrder').onclick=async()=>{try{await api('orders/'+id+'/cancel',{},headers);sessionStorage.removeItem('forme_checkout_key');orderPage(id)}catch(e){$('#orderStatus').textContent=e.message}};
if(o.requests?.length)$('#orderActions').insertAdjacentHTML('beforeend','<h2>Support requests</h2>'+o.requests.map(r=>'<p>'+esc(r.type)+' · '+esc(r.status)+(r.reverseState?' · Return delivery: '+esc(r.reverseState):'')+(r.reverseAWB?' · '+esc(r.reverseAWB):'')+(r.replacementOrderId?' · Replacement '+esc(r.replacementOrderId):'')+(r.response?' · '+esc(r.response):'')+'</p>').join(''));if(o.shipment){$('#orderActions').insertAdjacentHTML('beforeend','<h2>Shipment tracking</h2><p>'+esc(o.shipment.courier||'Courier assignment pending')+' '+esc(o.shipment.awb||'')+'</p><button id="refreshTrack" class="store-button outline">Refresh courier tracking</button><div id="trackResult"></div>');$('#refreshTrack').onclick=async()=>{try{const d=await api('orders/'+id+'/tracking',{},headers);$('#trackResult').innerHTML='<p>'+esc(d.status)+'</p>'+d.activities.slice(0,10).map(a=>'<p class="store-muted">'+esc(a.date)+' · '+esc(a.activity)+' · '+esc(a.location)+'</p>').join('')}catch(e){$('#orderStatus').textContent=e.message}}}
if(!['cancelled','expired','refunded'].includes(o.status)){$('#orderActions').insertAdjacentHTML('beforeend','<h2>Need help with this order?</h2><form id="orderRequest" class="store-form"><label>Request<select name="type"><option value="cancellation">Cancellation before dispatch</option><option value="return">Return after delivery</option><option value="exchange">Size exchange after delivery</option></select></label><label class="check"><input type="checkbox" name="defective">Damaged, defective or incorrect item</label><label>Reason<textarea name="reason" required minlength="3" maxlength="1000"></textarea></label><p class="store-muted">Eligible requests are reviewed under our <a href="/returns">returns</a> and <a href="/refunds">refund policies</a>.</p><button class="store-button outline">Submit request</button></form>');$('#orderRequest').onsubmit=async e=>{e.preventDefault();try{await api('orders/'+id+'/request',{...Object.fromEntries(new FormData(e.target)),defective:e.target.defective.checked},headers);$('#orderStatus').textContent='Your request has been received for review.'}catch(err){$('#orderStatus').textContent=err.message}}}
}catch(e){main.innerHTML=heading('YOUR ORDER','Let’s find your order.')+'<p>'+esc(e.message)+'</p><a href="/account">Sign in</a><p class="store-muted">For guest orders, use your saved private order link or contact support.</p>'}}
function tracking(){main.innerHTML=heading('KEEP UP WITH YOUR FORME','Track your order.','Use your order number and sign in, or open the private order link saved at checkout.')+'<form class="store-form store-panel" id="trackingForm" style="max-width:550px"><label>Order number<input name="order" placeholder="FRM-10001" pattern="FRM-[0-9]+" required></label><button class="store-button">Find order</button></form>';$('#trackingForm').onsubmit=e=>{e.preventDefault();location.href='/order-confirmation?id='+encodeURIComponent(e.target.order.value.trim().toUpperCase())}}
function contact(){main.innerHTML=heading('LET’S TALK FORME','Here for your everyday.')+'<div class="store-grid"><form id="contactForm" class="store-form store-panel"><label>Your name<input name="name" autocomplete="name" maxlength="80"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>How can we help?<textarea name="message" required minlength="10" maxlength="3000"></textarea></label><button class="store-button">Send to the studio</button><p class="store-status" id="contactStatus" role="status"></p></form><aside><h2>Customer support</h2><p>Monday–Saturday<br>10 AM–7 PM IST</p><p>Target initial response: within one business day.</p>'+(config.supportEmail?'<p><a href="mailto:'+esc(config.supportEmail)+'">'+esc(config.supportEmail)+'</a></p>':'<p class="store-muted">Official business email pending confirmation. Your message will be available in our support dashboard.</p>')+(config.whatsapp?'<a href="https://wa.me/'+esc(config.whatsapp)+'">WhatsApp support</a>':'')+'<h2>Custom & bulk orders</h2><p>Include your quantity, size split, design and required date. A quote and artwork approval are needed before production.</p></aside></div>';$('#contactForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await api('contact',Object.fromEntries(new FormData(e.target)));$('#contactStatus').textContent=r.message;e.target.reset()}catch(err){$('#contactStatus').textContent=err.message}finally{b.disabled=false}}}
async function init(){try{[config,products]=await Promise.all([api('config'),fetch('/api/products').then(r=>{if(!r.ok)throw Error('Collection unavailable');return r.json()})]);footer();if(!['account','forgot-password','reset-password','contact'].includes(page))consent();count();
if(!$('.store-body')){document.body.insertAdjacentHTML('afterbegin','<div class="preview-strip">'+(config.mode==='preview'?'Pre-launch preview · Live checkout opens after setup':config.mode!=='live'?esc(config.mode.toUpperCase())+' MODE · No live fulfilment':esc(config.announcement))+'</div>');(document.querySelector('.nav-right')||document.querySelector('.product-nav'))?.insertAdjacentHTML('beforeend','<div class="shop-links">'+(location.pathname.startsWith('/products/')?'<a href="/shop">Shop</a>':'')+'<a href="/account">Account</a>'+(location.pathname.startsWith('/products/')?'':'<a href="/wishlist">Wishlist</a>')+'<a href="/cart">Bag <span data-bag-count>0</span></a></div>');count();if(location.pathname.startsWith('/products/'))await productBuy();for(const b of config.banners)document.querySelector('main')?.insertAdjacentHTML('afterbegin','<section class="banner-campaign"><h2>'+esc(b.title)+'</h2><p>'+esc(b.text)+'</p><a href="'+esc(b.link)+'">Explore the edit</a></section>');return}
$('#storeAnnouncement').textContent=config.mode==='preview'?'Pre-launch preview · Live payments are not active':config.mode!=='live'?config.mode.toUpperCase()+' MODE · No live fulfilment':config.announcement;
document.title=({shop:'Shop all','new-arrivals':'New arrivals',essentials:'Plain essentials',graphics:'Graphic collection',cart:'Your bag',checkout:'Checkout',account:'Your account',wishlist:'Wishlist'}[page]||page.replaceAll('-',' '))+' | Forme';
const canonical=document.createElement('link');canonical.rel='canonical';canonical.href=location.origin+location.pathname;document.head.append(canonical);
if(['shop','new-arrivals','essentials','graphics','wishlist'].includes(page))shop(page);else if(['cart','checkout'].includes(page))await bagPage(page==='checkout');else if(page==='account')await account();else if(page==='orders')await orders();else if(page==='order-confirmation')await orderPage(new URLSearchParams(location.search).get('id')||'');else if(page==='track-order')tracking();else if(page==='contact')contact();else if(['forgot-password','reset-password'].includes(page))recovery();else if(!policy())main.innerHTML=heading('FORME','Page not found.')+'<a href="/shop">Explore the collection</a>';
}catch(e){if(main)main.innerHTML='<h1>We’ll be right back.</h1><p>'+esc(e.message)+'</p><button class="store-button" onclick="location.reload()">Try again</button>'}}
init();
})();
